BEGIN TRANSACTION;
CREATE TABLE agent_heuristics (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        topic TEXT NOT NULL,
        rule_statement TEXT NOT NULL,
        anti_pattern TEXT DEFAULT '',
        evidence_item_id INTEGER DEFAULT NULL,
        confidence_score REAL NOT NULL DEFAULT 1.0,
        execution_count INTEGER NOT NULL DEFAULT 0,
        success_count INTEGER NOT NULL DEFAULT 0,
        created_at INTEGER NOT NULL DEFAULT (strftime('%s', 'now')),
        updated_at INTEGER NOT NULL DEFAULT (strftime('%s', 'now')), rule_type TEXT DEFAULT 'MUST_DO',
        FOREIGN KEY (evidence_item_id) REFERENCES vault_items (id) ON DELETE SET NULL
    );
INSERT INTO "agent_heuristics" VALUES(1,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Context Window Overflows do nạp dữ liệu báo cáo tài chính lớn.','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Context Window Overflows do nạp dữ liệu báo cáo tài chính lớn.',15,1.0,0,0,1788887736,1788887736,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(2,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Hallucination từ LLM gây sai lệch tín hiệu giao dịch.','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Hallucination từ LLM gây sai lệch tín hiệu giao dịch.',15,1.0,0,0,1788887736,1788887736,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(3,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Độ trễ truyền thông giữa các Agent trong hệ thống phân tán.','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Độ trễ truyền thông giữa các Agent trong hệ thống phân tán.',19,1.0,0,0,1788887837,1788887837,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(4,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Hiện tượng lỗi lan truyền (Cascading Hallucination) do mã nguồn sinh ra tự động sai lệch từ bước trước.','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Hiện tượng lỗi lan truyền (Cascading Hallucination) do mã nguồn sinh ra tự động sai lệch từ bước trước.',19,1.0,0,0,1788887837,1788887837,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(5,'Hệ Thống Phân Tán, Backend & API Hiệu Năng Cao','Khi thiết kế Web-Systems, phải chủ động xử lý: Tiêu thụ tài nguyên RAM lớn khi chạy browser pool quy mô lớn.','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Tiêu thụ tài nguyên RAM lớn khi chạy browser pool quy mô lớn.',3,1.0,0,0,1788887928,1788887928,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(6,'Hệ Thống Phân Tán, Backend & API Hiệu Năng Cao','Khi thiết kế Web-Systems, phải chủ động xử lý: Rủi ro bị chặn IP bởi các hệ thống WAF/Anti-bot nâng cao nếu thiếu cấu hình proxy và stealth.','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Rủi ro bị chặn IP bởi các hệ thống WAF/Anti-bot nâng cao nếu thiếu cấu hình proxy và stealth.',3,1.0,0,0,1788887928,1788887928,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(7,'Hệ Thống Phân Tán, Backend & API Hiệu Năng Cao','Khi thiết kế Web-Systems, phải chủ động xử lý: Tăng độ phức tạp vận hành mạng lưới (Network Latency & Partitions).','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Tăng độ phức tạp vận hành mạng lưới (Network Latency & Partitions).',8,1.0,0,0,1788887941,1788887941,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(8,'Hệ Thống Phân Tán, Backend & API Hiệu Năng Cao','Khi thiết kế Web-Systems, phải chủ động xử lý: Thách thức quản lý tính nhất quán dữ liệu phân tán (Distributed Transactions / Saga Pattern).','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Thách thức quản lý tính nhất quán dữ liệu phân tán (Distributed Transactions / Saga Pattern).',8,1.1,2,2,1788887941,1788888350,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(9,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Mất tính thân thiện giao tiếp xã hội của mô hình, có thể gây khó chịu cho người dùng phổ thông..','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Mất tính thân thiện giao tiếp xã hội của mô hình, có thể gây khó chịu cho người dùng phổ thông..',23,1.0,0,0,1788890046,1788890046,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(10,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Rủi ro hiểu lầm ngữ cảnh do thiếu phần giải thích chi tiết nếu tác vụ quá phức tạp..','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Rủi ro hiểu lầm ngữ cảnh do thiếu phần giải thích chi tiết nếu tác vụ quá phức tạp..',23,1.0,0,0,1788890046,1788890046,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(11,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Khả năng thích ứng của Agent phụ thuộc vào chất lượng context website mục tiêu khi trích xuất brand assets..','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Khả năng thích ứng của Agent phụ thuộc vào chất lượng context website mục tiêu khi trích xuất brand assets..',24,1.0,0,0,1788890071,1788890071,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(12,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Rủi ro phát sinh layout lệch chuẩn nếu prompt không giới hạn nghiêm ngặt mật độ thông tin (target density)..','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Rủi ro phát sinh layout lệch chuẩn nếu prompt không giới hạn nghiêm ngặt mật độ thông tin (target density)..',24,1.0,0,0,1788890071,1788890071,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(13,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Xung đột phân tích cú pháp (parser) khi chồng chéo các phương thức cài đặt plugin scopes..','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Xung đột phân tích cú pháp (parser) khi chồng chéo các phương thức cài đặt plugin scopes..',25,1.0,0,0,1788890093,1788890093,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(14,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Hiện tượng trôi sự chú ý (attention drift) và quá tải Context Window nếu không cấu hình bộ lọc rules phù hợp..','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Hiện tượng trôi sự chú ý (attention drift) và quá tải Context Window nếu không cấu hình bộ lọc rules phù hợp..',25,1.0,0,0,1788890093,1788890093,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(15,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Cần giám sát tài nguyên và kiểm tra tính tương thích.','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Cần giám sát tài nguyên và kiểm tra tính tương thích.',26,1.0,0,0,1788890116,1788890116,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(16,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Vi phạm chuỗi phụ thuộc (bỏ qua nút product-marketing gốc dẫn đến agent suy diễn sai lệch ngữ cảnh).','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Vi phạm chuỗi phụ thuộc (bỏ qua nút product-marketing gốc dẫn đến agent suy diễn sai lệch ngữ cảnh).',27,1.0,0,0,1788890139,1788890139,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(17,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Context window bloat nếu nạp chồng chéo quá nhiều micro-skills vào cùng một phiên làm việc.','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Context window bloat nếu nạp chồng chéo quá nhiều micro-skills vào cùng một phiên làm việc.',27,1.0,0,0,1788890139,1788890139,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(18,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Overhead từ việc tạo quá nhiều git worktrees và subagent context switches trong các tác vụ nhỏ..','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Overhead từ việc tạo quá nhiều git worktrees và subagent context switches trong các tác vụ nhỏ..',28,1.0,0,0,1788890164,1788890164,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(19,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Rủi ro deadlocks hoặc xung đột trạng thái nếu cấu trúc task decomposition không chính xác..','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Rủi ro deadlocks hoặc xung đột trạng thái nếu cấu trúc task decomposition không chính xác..',28,1.0,0,0,1788890164,1788890164,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(20,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Cần giám sát tài nguyên và kiểm tra tính tương thích.','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Cần giám sát tài nguyên và kiểm tra tính tương thích.',29,1.0,0,0,1788890187,1788890187,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(21,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Thực thi I/O với quyền tiến trình gốc, rủi ro bảo mật SSRF và Path Traversal nếu không sanitize input..','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Thực thi I/O với quyền tiến trình gốc, rủi ro bảo mật SSRF và Path Traversal nếu không sanitize input..',30,1.0,0,0,1788890214,1788890214,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(22,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Chi phí API Cloud tăng đột biến khi gọi Azure Content Understanding hàng loạt trên dữ liệu lớn không phân loại..','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Chi phí API Cloud tăng đột biến khi gọi Azure Content Understanding hàng loạt trên dữ liệu lớn không phân loại..',30,1.0,0,0,1788890214,1788890214,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(23,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Khả năng đồng bộ phiên bản Firefox upstream chậm hơn so với các bản phát hành chính thức.','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Khả năng đồng bộ phiên bản Firefox upstream chậm hơn so với các bản phát hành chính thức.',31,1.0,0,0,1788890241,1788890241,'MUST_DO');
INSERT INTO "agent_heuristics" VALUES(24,'Kiến Trúc Multi-Agent & RAG Nhận Thức Tự Hành','Khi thiết kế AI-Agents, phải chủ động xử lý: Nguy cơ rò rỉ bộ nhớ (Memory Leak) nếu quản lý vòng đời tiến trình lười không đóng tab đúng cách ở tải cao.','Bỏ qua kiểm soát hoặc cấu hình mặc định dẫn đến nguy cơ: Nguy cơ rò rỉ bộ nhớ (Memory Leak) nếu quản lý vòng đời tiến trình lười không đóng tab đúng cách ở tải cao.',31,1.0,0,0,1788890241,1788890241,'MUST_DO');
CREATE TABLE brain_associations (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        source_item_id INTEGER NOT NULL,
        target_item_id INTEGER NOT NULL,
        relation_type TEXT NOT NULL DEFAULT 'EXTENDS',
        insight_notes TEXT NOT NULL,
        confidence_score REAL NOT NULL DEFAULT 1.0,
        created_at INTEGER NOT NULL DEFAULT (strftime('%s', 'now')),
        FOREIGN KEY (source_item_id) REFERENCES vault_items (id) ON DELETE CASCADE,
        FOREIGN KEY (target_item_id) REFERENCES vault_items (id) ON DELETE CASCADE
    );
INSERT INTO "brain_associations" VALUES(1,15,16,'ALTERNATIVE','Cả hai giải pháp đều đối mặt với bài toán nghẽn cổ chai về Context Window và độ trễ (Latency) trong hệ thống đa tác nhân, nhưng áp dụng vào hai miền nghiệp vụ hoàn toàn khác nhau là tài chính định lượng và phát triển game 3D.',0.95,1788887734);
INSERT INTO "brain_associations" VALUES(2,15,14,'EXTENDS','Tài liệu A mở rộng ứng dụng thực tế của Tài liệu B bằng cách minh họa hiện tượng ảo giác LLM (Hallucination) và lỗi hệ thống chìm trong bối cảnh đa tác nhân phân tích tài chính, đồng thời bổ sung các thách thức về độ trễ và giới hạn ngữ cảnh.',0.95,1788887735);
INSERT INTO "brain_associations" VALUES(3,15,13,'EXTENDS','Tài liệu A mở rộng ứng dụng đa tác nhân vào tài chính định lượng, trong khi Tài liệu B cung cấp nền tảng runtime hiệu suất cao và tối giản để giải quyết các vấn đề về độ trễ và quản lý ngữ cảnh của hệ thống.',0.95,1788887736);
INSERT INTO "brain_associations" VALUES(4,19,16,'EXTENDS','Tài liệu A mở rộng mô hình tác nhân phân tán từ phát triển game 3D (B) sang tối ưu hóa năng suất tổng quát cho lập trình viên đơn lẻ. Điểm giao thoa kỹ thuật nằm ở bài toán quản lý ngữ cảnh và độ trễ, trong đó A bổ sung thêm các thách thức về kiểm soát an toàn Sandbox và lỗi lan truyền mã nguồn tự động.',0.95,1788887829);
INSERT INTO "brain_associations" VALUES(5,19,13,'EXTENDS','Tài liệu A mở rộng năng lực điều phối đa tác nhân song song của HydraFusion trên nền tảng kiến trúc tối giản, hiệu suất cao của Nanobot. Sự kết hợp này giải quyết bài toán băng thông nhận thức của solo dev nhưng đòi hỏi phải kiểm soát nghiêm ngặt rủi ro lỗi lan truyền và bảo mật sandbox dưới tải cao.',0.95,1788887833);
INSERT INTO "brain_associations" VALUES(6,19,15,'EXTENDS','Tài liệu A mở rộng mô hình đa tác nhân từ lĩnh vực tài chính (B) sang bài toán kỹ thuật phần mềm của Solo Dev, đồng thời đối mặt với rủi ro lỗi lan truyền (Cascading Hallucination) nghiêm trọng hơn so với hiện tượng ảo giác thông tin đơn thuần.',0.95,1788887837);
INSERT INTO "brain_associations" VALUES(7,3,20,'EXTENDS','Crawl4AI tối ưu hóa tầng nạp dữ liệu đầu vào (Data Ingestion) bằng cách giảm token rác, cung cấp ngữ cảnh sạch hoàn toàn bổ trợ cho hiệu năng suy luận và xử lý của vLLM ở tầng hạ tầng AI.',0.95,1788887926);
INSERT INTO "brain_associations" VALUES(8,3,7,'EXTENDS','Crawl4AI giải quyết bài toán tiền xử lý ngữ cảnh đầu vào (tối ưu token, lọc nhiễu web) trước khi nạp vào hệ thống LLM, trong khi vLLM tối ưu hóa tầng phân bổ bộ nhớ GPU (KV Cache) để xử lý chuỗi đó với QPS cao; cả hai kết hợp tạo thành một pipeline RAG hoàn chỉnh từ khâu thu thập dữ liệu đến suy luận.',0.95,1788887927);
INSERT INTO "brain_associations" VALUES(9,3,12,'EXTENDS','Crawl4AI cung cấp hạ tầng thu thập dữ liệu web tối ưu hóa token cho LLM, bổ sung trực tiếp cho lớp nạp dữ liệu đầu vào của hệ thống RAG khí hậu trên nền tảng Dify để nâng cao chất lượng tri thức.',0.95,1788887928);
INSERT INTO "brain_associations" VALUES(10,8,19,'EXTENDS','Tài liệu A cung cấp nền tảng phân rã nghiệp vụ Microservices để giảm tải hệ thống, trong khi tài liệu B mở rộng mô hình này sang tầng phát triển tự động hóa bằng AI đa tác nhân, đồng thời đối mặt với các bài toán tương đồng về lỗi lan truyền và độ trễ phân tán.',0.95,1788887938);
INSERT INTO "brain_associations" VALUES(11,8,16,'EXTENDS','Tài liệu A cung cấp nền tảng phân rã dịch vụ và xử lý bất đồng bộ, trong khi Tài liệu B mở rộng các nguyên lý đó vào miền chuyên biệt là điều phối đa tác nhân AI cho game 3D, đối mặt với thách thức quản lý trạng thái phân tán ở cấp độ thời gian thực.',0.95,1788887939);
INSERT INTO "brain_associations" VALUES(12,8,13,'ALTERNATIVE','Tài liệu A đề xuất giải pháp mở rộng quy mô bằng phân rã microservices và quản lý phân tán phức tạp, trong khi Tài liệu B lại đi theo hướng ngược lại là tối giản hóa kiến trúc để tối ưu hiệu suất AI agent, tạo nên sự đối lập thú vị giữa hai trường phái thiết kế.',0.95,1788887941);
INSERT INTO "brain_associations" VALUES(13,23,19,'EXTENDS','Tài liệu A tối ưu hóa giao diện đầu vào và hành vi mệnh lệnh trực tiếp cho từng Coding Agent, bổ sung hoàn hảo cho khung kiến trúc phân tán HydraFusion ở Tài liệu B bằng cách giảm thiểu độ trễ nhận thức và kiểm soát chặt chẽ từng bước thực thi độc lập.',0.95,1788890044);
INSERT INTO "brain_associations" VALUES(14,23,13,'EXTENDS','Tài liệu A tối ưu hóa giao tiếp tầng ngữ nghĩa bằng ruleset trực lệnh, bổ sung hoàn hảo cho triết lý cắt giảm tầng trừu tượng phần cứng/logic cốt lõi ở mức mã nguồn của Tài liệu B nhằm đạt hiệu năng tối đa.',0.95,1788890045);
INSERT INTO "brain_associations" VALUES(15,23,15,'EXTENDS','Tài liệu A giải quyết triệt để nút thắt ''Context Window Overflows'' và ''Latency cao'' của Tài liệu B bằng cách áp dụng ruleset tối ưu hóa mệnh lệnh trực tiếp và giới hạn 5 bước cho các Agent tài chính.',0.95,1788890046);
INSERT INTO "brain_associations" VALUES(16,24,16,'ALTERNATIVE','Cả hai giải pháp đều khai thác tác nhân AI để tự động hóa tài sản trực quan nhưng hoạt động ở hai miền độc lập: Tài liệu A tập trung tối ưu hóa rendering biểu đồ vector 2D trong kỹ-thuật phần mềm, trong khi Tài liệu B giải quyết bài toán phối hợp đa tác nhân phức tạp cho đồ họa 3D thời gian thực.',0.95,1788890069);
INSERT INTO "brain_associations" VALUES(17,24,15,'EXTENDS','Tài liệu A mở rộng năng lực trực quan hóa cho kiến trúc Multi-Agent của Tài liệu B, đồng thời giải quyết bài toán quản lý context window và nhiễu thông tin thông qua việc chuẩn hóa mật độ dữ liệu đầu ra.',0.95,1788890070);
INSERT INTO "brain_associations" VALUES(18,24,19,'EXTENDS','Tài liệu A cung cấp thư viện Agent Skill chuyên biệt để giải quyết bài toán trực quan hóa, bổ sung trực tiếp vào năng lực tạo sinh mã nguồn đa tác nhân của khung kiến trúc HydraFusion (B) nhằm giảm thiểu thao tác thủ công.',0.95,1788890071);
INSERT INTO "brain_associations" VALUES(19,25,13,'EXTENDS','Tài liệu A mở rộng năng lực quản lý ngữ cảnh và tự động hóa chu trình cho framework tối giản của Tài liệu B, tạo nên một hệ sinh thái AI agent vừa tinh gọn ở tầng lõi vừa mạnh mẽ ở tầng vận hành.',0.95,1788890091);
INSERT INTO "brain_associations" VALUES(20,25,19,'EXTENDS','Tài liệu A giải quyết bài toán tối ưu hóa context window và runtime memory ở tầng Agent Harness, bổ sung trực tiếp cho việc quản lý phân rã tác vụ và giảm thiểu lỗi lan truyền đa tác nhân của khung HydraFusion ở Tài liệu B.',0.95,1788890092);
INSERT INTO "brain_associations" VALUES(21,25,15,'EXTENDS','Tài liệu A mở rộng năng lực quản lý runtime memory và context window tổng quát từ Agent Harness, giúp giải quyết triệt để bài toán tràn ngữ cảnh và nhiễu dữ liệu chuyên ngành đang gặp phải trong hệ thống tài chính đa tác nhân ở Tài liệu B.',0.95,1788890093);
INSERT INTO "brain_associations" VALUES(22,26,19,'EXTENDS','Tài liệu A mở rộng năng lực thực thi đầu ra của các Agent trong khung HydraFusion (Tài liệu B) từ dạng văn bản/mã nguồn thông thường thành các đoạn mã kết xuất video HTML/CSS/TS tất định. Sự kết hợp này đòi hỏi cơ chế kiểm soát lỗi lan truyền nghiêm ngặt từ HydraFusion để xử lý rủi ro sinh mã đồ họa sai lệch ở HyperFrames.',0.95,1788890114);
INSERT INTO "brain_associations" VALUES(23,26,13,'EXTENDS','HyperFrames mở rộng tư duy tối giản và hiệu suất cao của Nanobot bằng cách áp dụng phương pháp lập trình mã nguồn (HTML/CSS/TS) vào miền kết xuất video, chuyển đổi các tác vụ phức tạp thành đầu ra tất định dưới sự kiểm soát của AI Agent.',0.95,1788890115);
INSERT INTO "brain_associations" VALUES(24,26,16,'EXTENDS','Tài liệu A mở rộng tư duy điều phối agent từ phát triển game 3D tổng quát sang miền kết xuất video chuyên biệt, thay thế các API dựng hình phức tạp bằng việc chuẩn hóa mã nguồn HTML/CSS/TS.',0.95,1788890116);
INSERT INTO "brain_associations" VALUES(25,27,14,'EXTENDS','Tài liệu A cung cấp giải pháp kỹ thuật cụ thể (đồ thị DAG dạng Markdown) nhằm hiện thực hóa mục tiêu kiểm soát rủi ro nhận thức và chống ảo giác được đặt ra ở Tài liệu B.',0.95,1788890137);
INSERT INTO "brain_associations" VALUES(26,27,15,'EXTENDS','Tài liệu A cung cấp tầng tri thức ngữ nghĩa dạng DAG giúp giải quyết tận gốc bài toán hallucination và tối ưu hóa context window của hệ thống đa tác nhân tài chính ở Tài liệu B.',0.95,1788890138);
INSERT INTO "brain_associations" VALUES(27,27,13,'EXTENDS','Tài liệu A cung cấp tầng tri thức ngữ nghĩa dạng DAG để định hướng AI Coding Agents, bổ sung hoàn hảo cho lớp runtime hiệu suất cao và tối giản của Nanobot ở Tài liệu B, giúp giảm thiểu rủi ro hallucination khi xử lý các ngữ cảnh phức tạp.',0.95,1788890139);
INSERT INTO "brain_associations" VALUES(28,28,19,'EXTENDS','Tài liệu A bổ sung các cơ chế thực thi kỹ thuật cấp độ thấp (TDD, Git Worktrees, Subagents) để giải quyết các rủi ro về độ trễ ngữ cảnh và lỗi lan truyền vốn được nêu ra trong mô hình vĩ mô của Tài liệu B.',0.95,1788890162);
INSERT INTO "brain_associations" VALUES(29,28,13,'EXTENDS','Tài liệu A bổ sung quy trình quản lý trạng thái chặt chẽ và cơ chế kiểm định đa tầng cho framework tối giản của Tài liệu B, đánh đổi độ trễ và overhead để giải quyết triệt để vấn đề phân rã ngữ cảnh của LLM.',0.95,1788890163);
INSERT INTO "brain_associations" VALUES(30,28,14,'EXTENDS','Tài liệu A cung cấp khung kỹ thuật thực thi (TDD, Git Worktrees, subagents) nhằm giải quyết triệt để các rủi ro về suy giảm ngữ cảnh và ảo giác tự tin được nhận diện ở Tài liệu B.',0.95,1788890164);
INSERT INTO "brain_associations" VALUES(31,29,13,'EXTENDS','Tài liệu A bổ sung tầng kiểm soát hành vi (guardrail) rất cần thiết để giảm thiểu rủi ro bảo mật và sự thiếu hụt abstraction phòng thủ được chỉ ra trong kiến trúc tối giản của Tài liệu B.',0.95,1788890185);
INSERT INTO "brain_associations" VALUES(32,29,14,'EXTENDS','Tài liệu A cung cấp giải pháp kỹ thuật cụ thể là hệ thống Guardrail, trực tiếp giải quyết bài toán rủi ro ảo giác tự tin cao và lỗi chìm được cảnh báo trong Tài liệu B bằng cách biến AI thành một Constraint Solver.',0.95,1788890186);
INSERT INTO "brain_associations" VALUES(33,29,15,'EXTENDS','Tài liệu A cung cấp tầng cấu hình Guardrail và ràng buộc hành vi từ Karpathy, có thể được tích hợp trực tiếp vào hệ thống Multi-Agent của Tài liệu B nhằm giải quyết triệt để vấn đề Hallucination và kiểm soát ngữ cảnh của LLM.',0.95,1788890187);
INSERT INTO "brain_associations" VALUES(34,30,3,'EXTENDS','Crawl4AI và Microsoft MarkItDown bổ sung hoàn hảo cho nhau trong RAG pipeline: Crawl4AI tối ưu hóa việc thu thập và làm sạch dữ liệu từ web, trong khi MarkItDown chuẩn hóa đa dạng các định dạng tệp tin phi cấu trúc thành Markdown.',0.95,1788890211);
INSERT INTO "brain_associations" VALUES(35,30,14,'EXTENDS','Tài liệu A cung cấp công cụ chuẩn hóa dữ liệu đầu vào bằng Microsoft MarkItDown nhằm giải quyết bài toán đa định dạng cho LLM, nhưng phải chịu rủi ro bảo mật I/O và chi phí API, điều này bổ sung trực tiếp cho lớp kiểm soát rủi ro và quản trị nền tảng dữ liệu tại Tài liệu B.',0.95,1788890213);
INSERT INTO "brain_associations" VALUES(36,30,20,'EXTENDS','Tài liệu A giải quyết khâu tiền xử lý dữ liệu đầu vào cho RAG pipeline, trong khi Tài liệu B tối ưu hóa tầng suy luận LLM; sự kết hợp này tạo nên một luồng xử lý đầu cuối toàn diện từ tài liệu thô đến thông lượng suy luận cao.',0.95,1788890214);
INSERT INTO "brain_associations" VALUES(37,31,3,'EXTENDS','Camofox Browser bổ sung trực tiếp cho Crawl4AI bằng cách giải quyết điểm yếu cốt lõi về chống phát hiện bot và tối ưu hóa token từ tầng C++ của trình duyệt, giúp Crawl4AI vượt qua các hệ thống WAF nâng cao và tiết kiệm tài nguyên RAM đáng kể ở quy mô lớn.',0.95,1788890239);
INSERT INTO "brain_associations" VALUES(38,31,13,'EXTENDS','Camofox Browser bổ sung tầng trình duyệt kháng bot chuyên biệt bằng C++ cho AI Agents, kết hợp hoàn hảo với kiến trúc tối giản và multi-agent runtime hiệu suất cao của Nanobot.',0.95,1788890240);
INSERT INTO "brain_associations" VALUES(39,31,19,'EXTENDS','Camofox Browser cung cấp tầng thực thi trình duyệt kháng bot hiệu quả cho các AI Agents, bổ sung hoàn hảo cho lớp tác vụ web-scraping và tự động hóa trong khung đa tác nhân HydraFusion.',0.95,1788890241);
